//! Python RNS 1.5.5 golden-vector lock for tunnel synthesis.
//!
//! `../vectors/tunnel_vectors.json` is generated by the REAL Python
//! `Transport.synthesize_tunnel`, with upstream's own interface `str()` and `get_hash()`, a fixed
//! identity and a fixed random hash (`vectors/gen_tunnel_vectors.py`) — upstream-only vectors,
//! never re-derived. The lite builder must reproduce those packets byte for byte.

use rns_lite_core::constants::HEADER_MINSIZE;
use rns_lite_core::identity::LocalIdentity;
use rns_lite_core::tunnel::{
    TUNNEL_SYNTHESIS_LEN, TUNNEL_SYNTHESIS_PACKET_LEN, build_tunnel_synthesis_packet,
    interface_hash,
};
use rns_lite_core::wire::{HeaderType, packet_hash, sha256};

const VECTORS: &str = include_str!("../vectors/tunnel_vectors.json");
const SYNTHESES: [&str; 4] = [
    "first_connect",
    "first_reconnect",
    "second_connect",
    "second_reconnect",
];

fn from_hex(s: &str) -> Vec<u8> {
    assert!(s.len().is_multiple_of(2), "odd hex length");
    (0..s.len() / 2)
        .map(|i| u8::from_str_radix(&s[2 * i..2 * i + 2], 16).unwrap())
        .collect()
}

/// Raw JSON value text following `"key":`. The vectors hold only strings without escapes or
/// braces, and objects of them.
fn value<'a>(json: &'a str, key: &str) -> &'a str {
    let tag = format!("\"{key}\":");
    let at = json
        .find(&tag)
        .unwrap_or_else(|| panic!("missing key {key}"))
        + tag.len();
    json[at..].trim_start()
}

fn object<'a>(json: &'a str, key: &str) -> &'a str {
    let v = value(json, key);
    assert!(v.starts_with('{'), "{key} is not an object");
    let mut depth = 0;
    for (index, byte) in v.bytes().enumerate() {
        match byte {
            b'{' => depth += 1,
            b'}' => {
                depth -= 1;
                if depth == 0 {
                    return &v[..=index];
                }
            }
            _ => {}
        }
    }
    panic!("{key} is unterminated");
}

fn string<'a>(json: &'a str, key: &str) -> &'a str {
    let v = value(json, key);
    assert!(v.starts_with('"'), "{key} is not a string");
    &v[1..v[1..].find('"').unwrap() + 1]
}

fn bytes<const N: usize>(json: &str, key: &str) -> [u8; N] {
    from_hex(string(json, key))
        .try_into()
        .unwrap_or_else(|_| panic!("{key} is not {N} bytes"))
}

#[test]
fn vectors_come_from_the_pinned_python_validator() {
    assert_eq!(
        string(VECTORS, "rns_version"),
        include_str!("../vectors/RNS_VERSION").trim()
    );
}

#[test]
fn interface_hashes_match_python() {
    let interfaces = object(VECTORS, "interfaces");
    for case in ["tcp_ipv4", "tcp_ipv6", "tcp_hostname"] {
        let interface = object(interfaces, case);
        assert_eq!(
            interface_hash(string(interface, "str")),
            bytes::<32>(interface, "hash"),
            "{case}"
        );
    }
}

#[test]
fn syntheses_match_python_byte_for_byte() {
    let destination = bytes::<16>(VECTORS, "synthesize_destination_hash");
    let identities = object(VECTORS, "identities");
    let interfaces = object(VECTORS, "interfaces");
    let syntheses = object(VECTORS, "syntheses");
    for case in SYNTHESES {
        let synthesis = object(syntheses, case);
        let identity = object(identities, string(synthesis, "identity"));
        let lite = LocalIdentity::from_private_key(&bytes::<64>(identity, "private_key"));
        assert_eq!(lite.public_key(), &bytes::<64>(identity, "public_key"));

        let interface = object(interfaces, string(synthesis, "interface"));
        let mut out = [0u8; TUNNEL_SYNTHESIS_PACKET_LEN];
        let len = build_tunnel_synthesis_packet(
            &lite,
            &interface_hash(string(interface, "str")),
            &bytes::<16>(synthesis, "random_hash"),
            &mut out,
        )
        .unwrap();

        let raw = &out[..len];
        assert_eq!(raw, from_hex(string(synthesis, "raw")).as_slice(), "{case}");
        assert_eq!(
            &raw[HEADER_MINSIZE..],
            from_hex(string(synthesis, "payload")).as_slice(),
            "{case}"
        );
        assert_eq!(raw.len() - HEADER_MINSIZE, TUNNEL_SYNTHESIS_LEN);
        assert_eq!(&raw[2..18], &destination);
        assert_eq!(
            packet_hash(raw, HeaderType::Header1),
            bytes::<32>(synthesis, "packet_hash"),
            "{case}"
        );
        // Python's tunnel id: SHA-256(public_key || interface_hash).
        assert_eq!(
            sha256(&raw[HEADER_MINSIZE..HEADER_MINSIZE + 96]),
            bytes::<32>(synthesis, "tunnel_id"),
            "{case}"
        );
    }
}
